def human_bytes(size, binary=True):
    step = 1024 if binary else 1000
    units = ['B', 'KB', 'MB', 'GB', 'TB']
    value = float(size)
    for unit in units:
        if value < step or unit == units[-1]:
            return f'{value:.1f} {unit}' if unit != 'B' else f'{int(value)} B'
        value /= step

for size in (0, 512, 1536, 1048576, 5 * 1024 ** 3):
    print(f'{size:>14,} -> {human_bytes(size):>10} | decimal: {human_bytes(size, binary=False)}')

