import sys

USAGE = 'usage: report.py <rows:int> [--format=text|json]'

def parse_args(argv):
    if not argv:
        raise SystemExit(f'missing rows\n{USAGE}')
    rows_raw = argv[0]
    try:
        rows = int(rows_raw)
    except ValueError:
        raise SystemExit(f'rows must be an integer, got {rows_raw!r}\n{USAGE}') from None
    if rows <= 0:
        raise SystemExit(f'rows must be positive, got {rows}')
    fmt = 'text'
    for arg in argv[1:]:
        if arg.startswith('--format='):
            fmt = arg.split('=', 1)[1]
    if fmt not in ('text', 'json'):
        raise SystemExit(f'unknown format {fmt!r}\n{USAGE}')
    return rows, fmt

def main(argv):
    rows, fmt = parse_args(argv)
    if fmt == 'json':
        print('[' + ', '.join('{"row": %d}' % i for i in range(1, rows + 1)) + ']')
    else:
        for i in range(1, rows + 1):
            print(f'row {i:>3} | value {i * i:>6}')
    return 0

print('exit code:', main(['3']))
print('json mode :', end=' ')
print('exit code:', main(['2', '--format=json']))
