def print_table(headers, rows, formats):
    cells = [[FORMATTERS[fmt](value) for fmt, value in zip(formats, row)] for row in rows]
    widths = [max(len(headers[i]), *(len(r[i]) for r in cells)) for i in range(len(headers))]

    def line(values, numeric):
        parts = []
        for i, value in enumerate(values):
