import io, json, sys
from contextlib import redirect_stdout, redirect_stderr

COLUMNS = ('id', 'name', 'amount')

FORMATS = ('text', 'csv', 'jsonl')

def is_valid(row):
    return isinstance(row.get('id'), int) and isinstance(row.get('amount'), (int, float)) and bool(row.get('name'))

def render_text(rows):
    widths = [max(len(c), *(len(str(r[c])) for r in rows)) for c in COLUMNS]
    out = [' | '.join(f'{c:<{widths[i]}}' for i, c in enumerate(COLUMNS))]
    for row in rows:
        out.append(' | '.join(f'{str(row[c]):>{widths[i]}}' if isinstance(row[c], (int, float)) else f'{row[c]:<{widths[i]}}' for i, c in enumerate(COLUMNS)))
    return '\n'.join(out)

def render_csv(rows):
    def field(v):
        text = str(v)
        return '"' + text.replace('"', '""') + '"' if any(ch in text for ch in ',"\n') else text
    lines = [','.join(COLUMNS)]
    lines += [','.join(field(row[c]) for c in COLUMNS) for row in rows]
    return '\n'.join(lines)

def render_jsonl(rows):
    return '\n'.join(json.dumps({c: row[c] for c in COLUMNS}) for row in rows)

RENDERERS = {'text': render_text, 'csv': render_csv, 'jsonl': render_jsonl}

def emit(rows, fmt, out=sys.stdout):
    if fmt not in RENDERERS:
        raise ValueError(f'unknown format {fmt!r}; choose from {FORMATS}')
    valid = [r for r in rows if is_valid(r)]
    skipped = len(rows) - len(valid)
    if valid:
        print(RENDERERS[fmt](valid), file=out)
    print(f'{len(valid)} rows ok, {skipped} skipped', file=sys.stderr)
    return len(valid), skipped

