def bucketize(old, new):
    removed = sorted(set(old) - set(new))
    added = sorted(set(new) - set(old))
    changed = sorted(k for k in set(old) & set(new) if old[k] != new[k])
    same = sorted(k for k in set(old) & set(new) if old[k] == new[k])
    return removed, added, changed, same

def print_diff(old, new):
    removed, added, changed, same = bucketize(old, new)
    width = max((len(k) for k in set(old) | set(new)), default=0)
    arrow = ' -> '

    def section(title, keys, render):
        print(f'{title} ({len(keys)})')
        if not keys:
            print('  (none)')
        for key in keys:
            print(f'  {key:<{width}}{render(key)}')

    section('CHANGED', changed, lambda k: f'  {old[k]!r}{arrow}{new[k]!r}')
    section('ADDED', added, lambda k: f'  {new[k]!r}')
    section('REMOVED', removed, lambda k: f'  {old[k]!r}')
    print(f'UNCHANGED ({len(same)}): ' + ', '.join(same) if same else 'UNCHANGED (0)')

