import json

FORMATTERS = {
    'text': (str, '<'),
    'int': (lambda v: f'{v:,d}', '>'),
    'money': (lambda v: f'{v:,.2f}', '>'),
    'percent': (lambda v: f'{v:.1%}', '>'),
}

SPEC = [
    ('name', 'Employee', 'text'),
    ('dept', 'Department', 'text'),
    ('salary', 'Salary', 'money'),
    ('hike', 'Hike', 'percent'),
]

ROWS = [
    {'name': 'Anjali', 'dept': 'DB2 Team', 'salary': 122000, 'hike': 0.082},
    {'name': 'Rehan', 'dept': 'Testing', 'salary': 120000, 'hike': 0.045},
    {'name': 'Salman', 'dept': 'Data Engineering', 'salary': 125000, 'hike': 0.12},
    {'name': 'Broken', 'dept': None, 'salary': 'n/a', 'hike': 0.1},
]

def validate(row):
    problems = []
    for key, _, kind in SPEC:
        value = row.get(key)
        if value is None:
            problems.append(f'{key} missing')
        elif kind in ('money', 'percent') and not isinstance(value, (int, float)):
            problems.append(f'{key} not numeric ({value!r})')
    return problems

def clean(rows):
    good, rejected = [], []
    for row in rows:
        problems = validate(row)
        if problems:
            rejected.append((row.get('name', '?'), problems))
        else:
            good.append(row)
    return good, rejected

def render_text(rows):
    cells = [[FORMATTERS[kind][0](row[key]) for key, _, kind in SPEC] for row in rows]
    labels = [label for _, label, _ in SPEC]
    widths = [max([len(labels[i])] + [len(c[i]) for c in cells]) for i in range(len(SPEC))]
    lines = [' | '.join(f'{labels[i]:<{widths[i]}}' for i in range(len(SPEC)))]
    lines.append('-+-'.join('-' * w for w in widths))
    for row in cells:
        parts = []
        for i, (_, _, kind) in enumerate(SPEC):
            parts.append(f'{row[i]:{FORMATTERS[kind][1]}{widths[i]}}')
        lines.append(' | '.join(parts))
    return chr(10).join(lines)

def render_csv(rows):
    def field(v):
        text = str(v)
        return '"' + text.replace('"', '""') + '"' if any(ch in text for ch in ',"\n') else text
    header = ','.join(key for key, _, _ in SPEC)
    body = [','.join(field(row[key]) for key, _, _ in SPEC) for row in rows]
    return chr(10).join([header] + body)

def render_json(rows):
    return json.dumps([{key: row[key] for key, _, _ in SPEC} for row in rows], indent=2)

RENDERERS = {'text': render_text, 'csv': render_csv, 'json': render_json}

