import io, json, sys
from contextlib import redirect_stderr, redirect_stdout

USAGE = 'usage: report [--format=text|csv|json] [--quiet]'
CSV_INPUT = 'id,name,amount\n1,idli,60\n2,dosa,80.5\n3,vada,40\n'
SPEC = [('id', int), ('name', str), ('amount', float)]

class UsageError(Exception):
    pass

def parse_args(argv):
    cfg = {'format': 'text', 'quiet': False}
    for arg in argv:
        if arg.startswith('--format='):
            value = arg.split('=', 1)[1]
            if value not in ('text', 'csv', 'json'):
                raise UsageError(f'unknown format {value!r}')
            cfg['format'] = value
        elif arg == '--quiet':
            cfg['quiet'] = True
        else:
            raise UsageError(f'unknown flag {arg!r}')
    return cfg

def load(text):
    lines = [line for line in text.splitlines() if line.strip()]
    if not lines:
        raise ValueError('input is empty')
    header = lines[0].split(',')
    if tuple(header) != tuple(name for name, _ in SPEC):
        raise ValueError(f'bad header {header}, expected {[n for n, _ in SPEC]}')
    rows, rejected = [], []
    for line in lines[1:]:
        parts = line.split(',')
        if len(parts) != len(SPEC):
            rejected.append((line, 'wrong column count'))
            continue
        try:
            rows.append({name: cast(value) for (name, cast), value in zip(SPEC, parts)})
        except ValueError:
            rejected.append((line, 'type conversion failed'))
    return rows, rejected

def render_text(rows):
    labels = [name for name, _ in SPEC]
    cells = [[f'{row[n]:,.2f}' if isinstance(row[n], float) else str(row[n]) for n, _ in SPEC] for row in rows]
    widths = [max([len(labels[i])] + [len(c[i]) for c in cells]) for i in range(len(SPEC))]
    out = [' | '.join(f'{labels[i]:<{widths[i]}}' for i in range(len(SPEC)))]
    out += [' | '.join(f'{cell:>{widths[i]}}' for i, cell in enumerate(row)) for row in cells]
    return '\n'.join(out)

def render_csv(rows):
    return '\n'.join([','.join(name for name, _ in SPEC)] + [','.join(str(row[name]) for name, _ in SPEC) for row in rows])

def render_json(rows):
    return json.dumps(rows, indent=2)

RENDERERS = {'text': render_text, 'csv': render_csv, 'json': render_json}

def main(argv, input_text=CSV_INPUT, stdout=sys.stdout, stderr=sys.stderr):
    try:
        cfg = parse_args(argv)
    except UsageError as e:
        print(f'error: {e}\n{USAGE}', file=stderr)
        return 2
    try:
        rows, rejected = load(input_text)
    except ValueError as e:
        print(f'error: {e}', file=stderr)
        return 1
    if not cfg['quiet']:
        print(f'loaded {len(rows)} rows, rejected {len(rejected)}', file=stderr)
    for line, reason in rejected:
        print(f'warn: skipping {line!r} ({reason})', file=stderr)
    print(RENDERERS[cfg['format']](rows), file=stdout)
    return 0

for argv in (['--format=csv'], ['--format=json', '--quiet'], ['--format=xml'], ['--bogus']):
    out, err = io.StringIO(), io.StringIO()
    with redirect_stdout(out), redirect_stderr(err):
        code = main(argv, stdout=out, stderr=err)
    print(f'argv={argv} -> exit {code}')
    print('  stdout:', out.getvalue().strip().replace(chr(10), ' | ')[:80])
    print('  stderr:', err.getvalue().strip().replace(chr(10), ' | ')[:80])

